insert into public.site_settings (id, display_name, full_name, twitter_handle, social_heading, biography, updated_label, updated_display, seo_title, seo_description, canonical_url, role_prefix, roles, profile_media_id) values (true, 'Farzine Hossen', 'MD. Farzine Hossen', '@farzinehossen', 'Social Profiles', 'I’m a focused and motivated developer with a passion for software development and artificial intelligence. I enjoy building smart, practical solutions to real-world problems. With a strong understanding of core concepts and hands-on project experience, I’m always eager to learn new things and use technology to make a positive impact.', 'Last Updated:', 'January 31, 2026', 'MD. Farzine Hossen', 'MD. Farzine Hossen is a software engineer and AI enthusiast with a passion for building innovative solutions. Explore his portfolio to see his projects and skills in software development, machine learning, and more.', 'https://farzine.vercel.app/', 'I''m', ARRAY['Software Engineer','AI Enthusiast']::text[], '13880d99-6d9a-59c4-ae83-447d73a9b729') on conflict do nothing;
