insert into public.experiences (id, organization, role, date_label, bullets, url, sort_order, is_visible) values ('7de12af9-e187-5ae7-ae21-19d4d94e4290', 'Kite Games Studio', 'Software Engineer Intern (Machine Learning)', 'Nov 2025 - Feb 2026', ARRAY['Fine-tuned DL models like Kontext.dev, using LoRA, improving model efficiency for in-house projects.','Applied prompt engineering techniques to optimize generative AI outputs for game-related applications.','Documented workflows and presented findings to the team, ensuring reproducibility and knowledge transfer.']::text[], 'https://kitegamesstudio.com/', 0, false) on conflict do nothing;
insert into public.experiences (id, organization, role, date_label, bullets, url, sort_order, is_visible) values ('8f78b550-5ad8-5c6b-a254-eb33f7abb566', 'App-concept.com GmbH', 'Software Engineer Intern (Frontend)', 'May 2025 - Oct 2025', ARRAY['Built and maintained responsive web applications using Next.js, enhancing user experience and performance.','Implemented reusable UI components and optimized state management.','Worked closely with designers using Figma to translate wireframes into production-ready features.']::text[], 'https://app-concept.com/', 1, false) on conflict do nothing;
