insert into public.projects (id, title, category, slug, detail_title, paragraphs, technologies, source_url, demo_url, download_url, summary, cover_media_id, status, sort_order) values ('2e55f80a-6bda-5995-aa2e-fdcda0881d18', 'GSA-SUST website', 'Web', 'gsa-sust', 'Gaibandha Students Association Website', ARRAY['Developed a full-stack web platform with a dedicated admin panel for the Gaibandha Student Association at SUST to manage member activities, events, gallery, notices, and member information.','Implemented a user-friendly interface using NextJS and NodeJS, allowing members to easily access information and updates related to the association.','Integrated a robust admin panel for efficient management of member activities, events, and notices, enhancing the overall functionality and user experience of the platform.']::text[], ARRAY['NodeJS','NextJS','ExpressJS','Node Mailer','MongoDB','Cloudinary']::text[], '', 'https://www.gsa-sust.org/', '', 'Developed a full-stack web platform with a dedicated admin panel for the Gaibandha Student Association at SUST to manage member activities, events, gallery, notices, and member information.', '8a68d7f3-716c-5082-a8f4-6dafa9d44860', 'draft', 0) on conflict do nothing;
insert into public.projects (id, title, category, slug, detail_title, paragraphs, technologies, source_url, demo_url, download_url, summary, cover_media_id, status, sort_order) values ('cffb7bbf-1fa3-5db6-ad79-679fda1e7f67', 'ICERIE-2025', 'Web', 'icerie', 'ICERIE-2025', ARRAY['Developed the official website for ICERIE 2025 at SUST to showcase conference details, manage registrations and payments, display schedules, and provide updates for participants and organizers.','','Implemented a user-friendly interface using NextJS and NodeJS, allowing participants to easily access information and updates related to the conference.','']::text[], ARRAY['NodeJS','NextJS','ExpressJS','MongoDB','SUST e-payments','Javascript','Cloudinary']::text[], '', 'https://icerie2025.sust.edu/', '', 'Developed the official website for ICERIE 2025 at SUST to showcase conference details, manage registrations and payments, display schedules, and provide updates for participants and organizers.', 'b07ecd5a-d557-51fa-a5ba-45f718736453', 'draft', 1) on conflict do nothing;
insert into public.projects (id, title, category, slug, detail_title, paragraphs, technologies, source_url, demo_url, download_url, summary, cover_media_id, status, sort_order) values ('30a42709-e8d2-5317-a354-af95169e310b', 'ICAP-2025', 'Web', 'icap', 'ICAP-2025', ARRAY['Built the official website for ICAP 2025 at SUST to provide conference information, facilitate participant registration, and manage schedules, announcements, and updates for attendees and organizers.','The website serves as a comprehensive platform for the International Conference on Advanced Physics (ICAP) 2025, offering essential details about the conference, including schedules, speaker information, and registration options. It also features a user-friendly interface for participants to access important announcements and updates related to the event.']::text[], ARRAY['NodeJS','NextJS','ExpressJS','TailwindCSS','MongoDB','SSLCOMMERZ']::text[], '', 'https://icap2025.sust.edu/', '', 'Built the official website for ICAP 2025 at SUST to provide conference information, facilitate participant registration, and manage schedules, announcements, and updates for attendees and organizers.', 'fb96325a-5a4e-5f4a-ad2e-771eccb577fd', 'draft', 2) on conflict do nothing;
insert into public.projects (id, title, category, slug, detail_title, paragraphs, technologies, source_url, demo_url, download_url, summary, cover_media_id, status, sort_order) values ('5afe1da2-7eec-5e64-a491-e09328cfb6fc', 'Effective Learning', 'Web', 'effective-learning', 'Effective-learning through improved prompt design', ARRAY['Developed a research data collection website utilizing few-shot prompting to gather user responses and feedback for studying effective learning through improved prompt design.','The website is designed to collect user responses and feedback on various prompts, enabling researchers to analyze the effectiveness of different prompt designs in enhancing learning outcomes. It employs few-shot prompting techniques to guide users in providing meaningful input, thereby facilitating a more structured and insightful data collection process.']::text[], ARRAY['Fewshot-prompting','GPT-API','NextJS','JavaScript','MOngoDB','TailwindCSS']::text[], '', 'https://effective-learning-nu.vercel.app/login', '', 'Developed a research data collection website utilizing few-shot prompting to gather user responses and feedback for studying effective learning through improved prompt design.', '090b946a-6421-5494-a346-66693d614a3c', 'draft', 3) on conflict do nothing;
insert into public.projects (id, title, category, slug, detail_title, paragraphs, technologies, source_url, demo_url, download_url, summary, cover_media_id, status, sort_order) values ('c076f3b3-b866-512b-a975-b27dd20122d0', 'FarmAI', 'Web', 'farmai', 'FarmAI', ARRAY['A deep learning-based crop disease detection and prevention system using YOLO, integrated with a related marketplace to support farmers with actionable insights and relevant resources.','FarmAI is a comprehensive solution designed to assist farmers in identifying and managing crop diseases. By leveraging advanced deep learning techniques, the platform provides real-time disease detection and actionable insights, empowering farmers to make informed decisions. The integration of a marketplace further enhances the user experience by offering relevant resources and products tailored to their needs.']::text[], ARRAY['NodeJS','NextJS','ExpressJS','MongoDB','Finetuned Yollo Model','GPT-API']::text[], 'https://github.com/Farzine/FarmAI', 'https://farm-ai-fz.vercel.app/', '', 'A deep learning-based crop disease detection and prevention system using YOLO, integrated with a related marketplace to support farmers with actionable insights and relevant resources.', 'd0b0d6d7-ed97-5ef4-aa5e-f36870f83de6', 'draft', 4) on conflict do nothing;
insert into public.projects (id, title, category, slug, detail_title, paragraphs, technologies, source_url, demo_url, download_url, summary, cover_media_id, status, sort_order) values ('76588b3d-0adc-54c9-abe8-ca1079a61e10', 'Online Player Auction Website', 'Web', 'chol-kheli', 'Chol-Kheli', ARRAY['Developed an online auction platform for cricket and football players, featuring live bidding, team and player management, and admin controls to facilitate seamless team formation and tournament setup','The project was developed as a part of my BSc in course project at the University. It was a collaborative effort with my team members, and I played a key role in the backend development using NodeJS and ExpressJS, as well as implementing real-time features using Web Socket. The platform allows users to register, create teams, and participate in live auctions for players, enhancing the overall experience of managing sports teams online.']::text[], ARRAY['NodeJS','ExpressJS','NextJS','Web Socket','MySQL']::text[], 'https://github.com/shaeakh/WebProject', '', '', 'Developed an online auction platform for cricket and football players, featuring live bidding, team and player management, and admin controls to facilitate seamless team formation and tournament setup', 'b47d416f-e9c6-5620-aabe-176aa36946d0', 'draft', 5) on conflict do nothing;
insert into public.projects (id, title, category, slug, detail_title, paragraphs, technologies, source_url, demo_url, download_url, summary, cover_media_id, status, sort_order) values ('a556dc73-9391-5345-ad95-148330643b27', 'Lemon Disease Detection', 'Web', 'lemonleafdiseasedetection', 'Lemon Leaf Disease Detection', ARRAY['The Lemon Leaf Disease Detection is a web application that uses a fine-tuned YOLO model to detect diseases in lemon leaves. The application is built using Next.js and utilizes the Roboflow platform for model training and deployment. The dataset used for training the model is sourced from Kaggle, ensuring high-quality data for accurate disease detection.','The application allows users to upload images of lemon leaves and receive real-time predictions on whether the leaves are healthy or affected by diseases. The fine-tuned YOLO model ensures high accuracy in detecting various diseases, making it a valuable tool for farmers and agricultural professionals.']::text[], ARRAY['Fine Tuned Yollow Model','Roboflow','NextJS','Dataset','Notebook','Kaggle']::text[], 'https://github.com/Farzine/LemonLeafDiseasesDetectionAI', 'https://lemon-leaf-diseases-detection-ai.vercel.app/', '', 'The Lemon Leaf Disease Detection is a web application that uses a fine-tuned YOLO model to detect diseases in lemon leaves. The application is built using Next.js and utilizes the Roboflow platform for model training and deployment. The dataset used for training the model is sourced from Kaggle, ensuring high-quality data for accurate disease detection.', '704edc3a-f00e-5ce8-aa44-4463eab8444e', 'draft', 6) on conflict do nothing;
insert into public.projects (id, title, category, slug, detail_title, paragraphs, technologies, source_url, demo_url, download_url, summary, cover_media_id, status, sort_order) values ('f1b1a910-08df-5479-a7ec-8b621fe38578', 'IICT-SUST', 'Web', 'iict', 'IICT-SUST', ARRAY['IICT-SUST is a comprehensive web application designed to facilitate the management of student information, course details, and faculty data for the Institute of Information and Communication Technology (IICT) at Shahjalal University of Science and Technology (SUST). The application features a user-friendly interface that allows students to register, view their courses, and access faculty information. Faculty members can manage their profiles and courses efficiently. The backend is powered by NodeJS with PostgreSQL as the database, ensuring robust data handling and security. The application also integrates Nodemailer for email notifications and Cloudinary for image storage.']::text[], ARRAY['NextJS','NodeJS','PostgreSQL','Nodemailer','Cloudinary']::text[], '', 'https://iict-sust-swe.vercel.app/', '', 'IICT-SUST is a comprehensive web application designed to facilitate the management of student information, course details, and faculty data for the Institute of Information and Communication Technology (IICT) at Shahjalal University of Science and Technology (SUST). The application features a user-friendly interface that allows students to register, view their courses, and access faculty information. Faculty members can manage their profiles and courses efficiently. The backend is powered by NodeJS with PostgreSQL as the database, ensuring robust data handling and security. The application also integrates Nodemailer for email notifications and Cloudinary for image storage.', '91f7608b-dd19-57fb-a6a7-9aef5282c44d', 'draft', 7) on conflict do nothing;
insert into public.projects (id, title, category, slug, detail_title, paragraphs, technologies, source_url, demo_url, download_url, summary, cover_media_id, status, sort_order) values ('8a5b276b-53ed-57f6-a879-3dd51670e868', 'DP-Learning App', 'App', 'dplearningapp', 'DP-Learning App', ARRAY['This is a mobile application designed to help users learn about design patterns in software development. It provides a user-friendly interface for exploring various design patterns, understanding their concepts, and implementing them in real-world scenarios. The app includes features such as interactive tutorials, code examples, quizzes, and a community forum for discussions. It aims to enhance the learning experience by providing practical insights and hands-on exercises related to design patterns.']::text[], ARRAY['Flutter','Dart','Riverpod','NodeJS','ExpressJS','MongoDB','Google Map','Gemini api']::text[], 'https://github.com/Farzine/Design-Pattern-Learning-App', '', '', 'This is a mobile application designed to help users learn about design patterns in software development. It provides a user-friendly interface for exploring various design patterns, understanding their concepts, and implementing them in real-world scenarios. The app includes features such as interactive tutorials, code examples, quizzes, and a community forum for discussions. It aims to enhance the learning experience by providing practical insights and hands-on exercises related to design patterns.', '988aa043-666c-5fa4-a59a-df2ec000e975', 'draft', 8) on conflict do nothing;
insert into public.projects (id, title, category, slug, detail_title, paragraphs, technologies, source_url, demo_url, download_url, summary, cover_media_id, status, sort_order) values ('36c6e0b3-8d8b-5f85-a908-69e6598301f6', 'Candle Stick', 'Web', 'candle-stick', 'Candle Stick', ARRAY['A candlestick chart visualization tool that displays Apple Inc. stock price data using Apache ECharts and shadcn UI components.','This project utilizes the Apache ECharts library to create an interactive candlestick chart that visualizes stock price movements over time. The chart is designed to provide insights into the stock''s performance, including opening, closing, high, and low prices for each trading day.']::text[], ARRAY['Apache ECharts','Shadcn','NextJS']::text[], 'https://github.com/Farzine/candle_stick', '', '', 'A candlestick chart visualization tool that displays Apple Inc. stock price data using Apache ECharts and shadcn UI components.', '795a1ab7-8412-59a1-a5be-b51cbc0a38b8', 'draft', 9) on conflict do nothing;
insert into public.projects (id, title, category, slug, detail_title, paragraphs, technologies, source_url, demo_url, download_url, summary, cover_media_id, status, sort_order) values ('19c83255-f08f-536f-ad32-d74d45c4a1e8', 'Waste Management App', 'App', 'wastemanagementapp', 'Waste Management App', ARRAY['The Waste Management App is a mobile application designed to facilitate the management and recycling of waste materials. It provides users with a platform to report waste issues, find recycling centers, and learn about proper waste disposal methods. The app integrates with Firebase for data storage and retrieval, and it uses Google Authentication for secure user login.']::text[], ARRAY['Flutter','Firebase','Google Auth']::text[], 'https://github.com/Farzine/waste_management_and_recycle_application', '', '', 'The Waste Management App is a mobile application designed to facilitate the management and recycling of waste materials. It provides users with a platform to report waste issues, find recycling centers, and learn about proper waste disposal methods. The app integrates with Firebase for data storage and retrieval, and it uses Google Authentication for secure user login.', '46fbfa7e-b1e4-5682-a03b-079cd82820d4', 'draft', 10) on conflict do nothing;
insert into public.projects (id, title, category, slug, detail_title, paragraphs, technologies, source_url, demo_url, download_url, summary, cover_media_id, status, sort_order) values ('51211de0-1234-5f08-a043-5b8f2add20f9', '3D Car Game', 'App', 'car', '3D Car Game', ARRAY['Developed a 3D car game using Unity and C#, featuring realistic physics, dynamic environments, and engaging gameplay. The game allows players to experience driving in a virtual world with various terrains and challenges.']::text[], ARRAY['Unity','C#']::text[], '', '', 'https://drive.google.com/file/d/1mmpk6zVzzfXqI4QIMUTt5bzG7AW0BrZU/view?usp=sharing', 'Developed a 3D car game using Unity and C#, featuring realistic physics, dynamic environments, and engaging gameplay. The game allows players to experience driving in a virtual world with various terrains and challenges.', '4b17f0d6-52a4-50bf-a980-7216aa794d5d', 'draft', 11) on conflict do nothing;
insert into public.projects (id, title, category, slug, detail_title, paragraphs, technologies, source_url, demo_url, download_url, summary, cover_media_id, status, sort_order) values ('6e8be83d-2b4f-5781-a45a-96d54d69b289', 'Brick Changer Game', 'App', 'brick', 'Brick Changer Game', ARRAY['Developed a Brick Changer game using Java and Java Swing, Here i learn how to use Java Swing for GUI development and implement game logic in Java.']::text[], ARRAY['Java','Java Swing']::text[], 'https://github.com/Farzine/Brick-Changer-Game', '', '', 'Developed a Brick Changer game using Java and Java Swing, Here i learn how to use Java Swing for GUI development and implement game logic in Java.', '32c6fa21-8f0c-58ef-a383-ba9d7234f526', 'draft', 12) on conflict do nothing;
insert into public.projects (id, title, category, slug, detail_title, paragraphs, technologies, source_url, demo_url, download_url, summary, cover_media_id, status, sort_order) values ('293c7d90-1246-59a4-a749-b41ad596c486', 'Golf Game with SFML', 'App', 'golf', 'Golf Game with SFML', ARRAY['Developed a console golf game using C++ and the SFML library, featuring realistic physics, multiple levels, and engaging gameplay.']::text[], ARRAY['C++','SFML library']::text[], 'https://github.com/Farzine/Golf_Game_SFML_GAME', '', '', 'Developed a console golf game using C++ and the SFML library, featuring realistic physics, multiple levels, and engaging gameplay.', 'c33ccba1-f41f-5b99-acf2-ec2239fcff48', 'draft', 13) on conflict do nothing;
insert into public.projects (id, title, category, slug, detail_title, paragraphs, technologies, source_url, demo_url, download_url, summary, cover_media_id, status, sort_order) values ('3fee4df5-4faf-5e78-aa7b-83769c8df4d2', 'Console Snake Game', 'App', 'snake', 'Console Snake Game', ARRAY['Developed a console-based Snake game using C++ and the Graphics.h library, featuring classic gameplay mechanics, dynamic levels, and engaging user interaction. The game allows players to control the snake, collect food, and grow in size while avoiding collisions.']::text[], ARRAY['C++','Graphics.h library']::text[], 'https://github.com/Farzine/first-snake-game-project-semester-1-2', '', '', 'Developed a console-based Snake game using C++ and the Graphics.h library, featuring classic gameplay mechanics, dynamic levels, and engaging user interaction. The game allows players to control the snake, collect food, and grow in size while avoiding collisions.', '55ce16d3-8801-5d57-a69c-73e81038d88e', 'draft', 14) on conflict do nothing;
